<?php require_once __DIR__ . '/db.php'; $sent=false; $formError=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$stmt=db()->prepare("INSERT INTO requests(request_type,guest_name,email,phone,preferred_reply,checkin_date,checkout_date,guests,budget,notes) VALUES('booking',?,?,?,?,?,?,?,?,?)");$stmt->execute([trim($_POST['name']??''),trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['reply']??''),trim($_POST['checkin']??''),trim($_POST['checkout']??''),trim($_POST['guests']??''),trim($_POST['budget']??''),trim($_POST['notes']??'')]);$sent=true;}catch(Throwable $e){$formError='We could not send your request just now. Please try again in a moment.';}} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request a stay — Cox Booking</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700&family=Noto+Serif+Bengali:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="bengali-ui.css"><link rel="stylesheet" href="pages.css"><link rel="stylesheet" href="forms.css"><link rel="stylesheet" href="responsive.css"></head><body><?php include 'partials.php';?><main class="form-page"><div class="form-layout wrap"><aside class="form-aside"><div class="eyebrow"><span></span> Your time by the sea</div><h1>Let’s find your<br><em>place.</em></h1><p>Tell us a little about the trip you have in mind. Our local team will get back to you personally.</p><div class="response-card"><span class="response-icon">✳</span><div><b>A real person, soon</b><small>We’ll reply by email or WhatsApp within 6 hours.</small></div></div><div class="aside-footnote">Just a request for now. Nothing is booked and no payment is required.</div></aside><section class="form-card"><div class="form-card-head"><span>STAY REQUEST</span><span>01 — 02</span></div><?php if($sent): ?><div class="success"><span>✓</span><h2>We’ve got your note.</h2><p>Thanks for reaching out. Our team will be in touch within six hours to help find your stay.</p><a class="text-link" href="index.php">Back to Cox Booking <b>↗</b></a></div><?php else: ?><h2>Tell us about your trip</h2><?php if($formError): ?><div class="admin-alert"><?=e($formError)?></div><?php endif; ?><form method="post" action="request.php"><?=csrf_field()?><div class="field-row"><label>Your name<input required name="name" autocomplete="name" placeholder="e.g. Samira Rahman"></label><label>Email address<input required type="email" name="email" autocomplete="email" placeholder="you@example.com"></label></div><div class="field-row"><label>WhatsApp number<input required type="tel" name="phone" autocomplete="tel" placeholder="+880 1XXX XXXXXX"></label><label>Preferred reply<input type="text" name="reply" placeholder="Email or WhatsApp"></label></div><div class="field-row"><label>Check-in date<input required type="text" name="checkin" placeholder="DD / MM / YYYY" inputmode="numeric"></label><label>Check-out date<input required type="text" name="checkout" placeholder="DD / MM / YYYY" inputmode="numeric"></label></div><div class="field-row"><label>Number of guests<input type="text" name="guests" placeholder="e.g. 2 adults, 1 child" inputmode="text"></label><label>Budget per night<input type="text" name="budget" placeholder="e.g. ৳ 5,000 – 8,000"></label></div><label class="full-field">Anything else we should know? <span class="optional">OPTIONAL</span><textarea name="notes" rows="3" placeholder="A hotel you liked, a view you’re dreaming of, a little one coming along…"></textarea></label><div class="form-submit"><button class="button submit-button" type="submit">Send stay request <span>↗</span></button><small>No payment, no commitment.<br>Just a helpful reply within 6 hours.</small></div></form><?php endif; ?></section></div></main><?php include 'footer.php';?></body></html>
